import{newSpecPage}from"@stencil/core/testing";import{ScSubscriptionDetails}from"../sc-subscription-details";const renewalText=async e=>{const t=await newSpecPage({components:[ScSubscriptionDetails],html:"<sc-subscription-details></sc-subscription-details>"});return t.root.subscription=e,await t.waitForChanges(),t.root.shadowRoot.textContent};describe("sc-subscription-details",(()=>{it("renders",(async()=>{const e=await newSpecPage({components:[ScSubscriptionDetails],html:"<sc-subscription-details></sc-subscription-details>"});expect(e.root).toMatchSnapshot()})),it("gives both dates when a pause is scheduled",(async()=>{expect(await renewalText({status:"active",cancel_at_period_end:1786e6,current_period_end_at:1786e6,current_period_end_at_date:"March 1, 2026",restore_at:1817e6,restore_at_date:"June 1, 2026"})).toContain("Your plan will be paused on March 1, 2026 and will resume on June 1, 2026")})),it("gives the resume date once the pause has taken effect",(async()=>{expect(await renewalText({status:"canceled",restore_at:1817e6,restore_at_date:"June 1, 2026"})).toContain("Your plan is paused and will resume on June 1, 2026")})),it("still says canceled when there is no restore date",(async()=>{expect(await renewalText({status:"active",cancel_at_period_end:1786e6,current_period_end_at:1786e6,current_period_end_at_date:"March 1, 2026",restore_at:null})).toContain("Your plan will be canceled on March 1, 2026")}))}));